              <button
                key={svc.id}
                onClick={() => {
                  setService(svc);
                  setMaster(null);
                  setHold(null);
                  setSlots(null);
                }}
                className={`flex items-center justify-between gap-3 rounded-xl border px-4 py-3 text-left transition ${
                  service?.id === svc.id
                    ? "border-zinc-900 bg-zinc-900 text-white"
