                    {" "}
                    · {svc.durationMin} min
                  </span>
                </span>
                <span className="shrink-0 font-medium">{fmtPrice(svc.priceKzt)}</span>
              </button>
            ))}
          </div>
        )}
      </section>

      {/* Step 2: master */}
      {service && (
        <section>
          <h2 className="mb-2 font-semibold text-zinc-800">2 · Staff member</h2>
