              >
                {m.name}
              </button>
            ))}
          </div>
        </section>
      )}

      {/* Step 3: date + slot */}
      {service && master && !hold && (
        <section>
          <h2 className="mb-2 font-semibold text-zinc-800">3 · Date and time</h2>
          <input
            type="date"
            value={date}
            min={new Date().toISOString().slice(0, 10)}
            onChange={(e) => {
              setDate(e.target.value);
