input.command:
cd /tmp/a11y && cat > probe.mjs <<'EOF'
import puppeteer from "puppeteer-core";
const browser = await puppeteer.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: true, args: ["--no-sandbox"] });
const page = await browser.newPage();
await page.goto("file:///tmp/a11y/index.html");
await page.addScriptTag({ path: "/tmp/a11y/node_modules/.pnpm/axe-core@4.13.0/node_modules/axe-core/axe.min.js" });
await page.evaluate(() => {
  document.getElementById("root").innerHTML = `
  <button id="sel" style="" class="rounded-full border px-4 py-2 border-zinc-900 bg-zinc-900 text-white">Aida</button>
  <span id="dur" class="text-zinc-300">· 60 min</span>
  <span id="dur2" class="text-zinc-600">· 60 min</span>
  <button id="plain" class="border-zinc-200 bg-white">Dana</button>`;
});
const out = await page.evaluate(async () => {
  const r = await axe.run("#root", { runOnly: ["color-contrast"], elementRef: false });
  const nodes = [...r.violations, ...r.incomplete].flatMap((v) => v.nodes.map((n) => ({ rule: v.id, target: n.target, msg: n.failureSummary, data: n.any.concat(n.all, n.none).map(c => c.data) })));
  const cs = (id) => { const s = getComputedStyle(document.getElementById(id)); return [s.color, s.backgroundColor]; };
  return { nodes, cs: { sel: cs("sel"), dur: cs("dur"), dur2: cs("dur2"), plain: cs("plain") } };
});
console.log(JSON.stringify(out, null, 1).slice(0, 4000));
await browser.close();
EOF
