import puppeteer from "puppeteer-core";
import fs from "node:fs";

const AXE = "/tmp/a11y/node_modules/.pnpm/axe-core@4.13.0/node_modules/axe-core/axe.min.js";
const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const browser = await puppeteer.launch({ executablePath: CHROME, headless: true, args: ["--no-sandbox"] });
const page = await browser.newPage();
await page.setViewport({ width: 480, height: 900 });
page.on("pageerror", (e) => console.log("PAGE ERROR:", e.message));

await page.evaluateOnNewDocument(() => {
  window.__scenario = { empty: false, holdFail: false, waitFail: false };
  const services = [
    { id: "s1", name: "Haircut", durationMin: 60, priceKzt: 5000, staff: [{ id: "m1", name: "Aida" }, { id: "m2", name: "Dana" }] },
    { id: "s2", name: "Beard trim", durationMin: 20, priceKzt: 2500, staff: [{ id: "m1", name: "Aida" }] },
  ];
  const json = (b, s = 200) => new Response(JSON.stringify(b), { status: s, headers: { "content-type": "application/json" } });
  const base = Date.UTC(2030, 0, 1, 4);
  window.fetch = async (url) => {
    const u = String(url);
    const sc = window.__scenario;
    if (u.includes("/catalog")) return json({ services });
    if (u.includes("/slots"))
      return json({ slots: sc.empty ? [] : [0, 1, 2, 3, 4, 5].map((i) => ({ startMs: base + i * 3600e3, endMs: base + (i + 1) * 3600e3 })) });
    if (u.includes("/hold"))
      return sc.holdFail ? json({ error: "slot_taken" }, 409) : json({ holdToken: "t", expiresInSec: 600, slot: { startMs: base, endMs: base + 3600e3 } });
    if (u.includes("/waitlist")) return sc.waitFail ? json({ error: "bad_request" }, 400) : json({ ok: true });
    if (u.includes("/book")) return json({ error: "slot_taken" }, 409);
    return json({}, 404);
  };
});

await page.goto("file:///tmp/a11y/index.html");
await page.addScriptTag({ path: AXE });

const waitText = (t) => page.waitForFunction((t) => document.body.innerText.includes(t), { timeout: 5000 }, t);
const clickText = (t, sel = "button") =>
  page.evaluate(
    (t, sel) => {
      const el = [...document.querySelectorAll(sel)].find((b) => b.textContent.includes(t));
      if (!el) throw new Error("no element " + t);
      el.click();
    },
    t,
    sel,
  );
const setScenario = (patch) => page.evaluate((p) => Object.assign(window.__scenario, p), patch);

async function audit(label) {
  const res = await page.evaluate(async () => {
    const r = await axe.run(document, { runOnly: { type: "tag", values: ["wcag2a", "wcag2aa"] } });
    return {
      violations: r.violations.map((v) => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map((n) => n.html.slice(0, 140)) })),
      passes: r.passes.length,
      alerts: [...document.querySelectorAll('[role="alert"]')].map((e) => e.textContent.trim()),
      statuses: [...document.querySelectorAll('[role="status"]')].map((e) => e.textContent.trim().slice(0, 60)),
      pressed: [...document.querySelectorAll('button[aria-pressed]')].map((b) => `${b.textContent.trim()}=${b.getAttribute("aria-pressed")}`),
    };
  });
  console.log(`\n== ${label}`);
  console.log("violations:", JSON.stringify(res.violations, null, 2));
  console.log("passes:", res.passes, "| alerts:", JSON.stringify(res.alerts), "| status:", JSON.stringify(res.statuses));
  console.log("aria-pressed:", JSON.stringify(res.pressed));
}

